// Basic aggregations
fetch logs, from: now() - 1h
| summarize {
total_logs = count(),
unique_hosts = countDistinct(dt.entity.host),
unique_namespaces = countDistinct(k8s.namespace.name),
unique_pods = countDistinct(k8s.pod.name)
}

// Aggregations with grouping
// status == "ERROR" covers every error-class level (ERROR, SEVERE, CRITICAL, FATAL, …);
// loglevel == "ERROR" alone misses SEVERE and the rest
fetch logs, from: now() - 1h
| summarize {
total = count(),
errors = countIf(status == "ERROR"),
warnings = countIf(status == "WARN"),
info = countIf(status == "INFO" AND NOT in(loglevel, {"DEBUG", "TRACE"}))
}, by: {k8s.namespace.name}
| sort total desc
| limit 15

// Error rate calculation
fetch logs, from: now() - 1h
| summarize {
total = count(),
errors = countIf(status == "ERROR")
}, by: {k8s.namespace.name}
| filter total > 100  // Minimum sample size
| fieldsAdd error_rate_pct = round((errors * 100.0) / total, decimals: 2)
| sort error_rate_pct desc
| limit 15

// Log volume over time (5-minute buckets)
fetch logs, from: now() - 6h
| makeTimeseries {log_count = count()}, interval: 5m

// Error trend over time
fetch logs, from: now() - 6h
| makeTimeseries {
total = count(),
errors = countIf(status == "ERROR"),
warnings = countIf(status == "WARN")
}, interval: 5m

// Time series by dimension (namespace)
fetch logs, from: now() - 6h
| filter isNotNull(k8s.namespace.name)
| makeTimeseries {
log_count = count()
}, by: {k8s.namespace.name}, interval: 10m

// Error rate time series by host
fetch logs, from: now() - 6h
| filter isNotNull(dt.entity.host)
| makeTimeseries {
total = count(),
errors = countIf(status == "ERROR")
}, by: {dt.entity.host}, interval: 15m

// Log volume statistics by source
fetch logs, from: now() - 24h
| summarize {
total = count(),
first_seen = min(timestamp),
last_seen = max(timestamp)
}, by: {dt.openpipeline.source}
// duration ÷ duration yields a number; a long ÷ duration would return null
| fieldsAdd span = last_seen - first_seen
| fieldsAdd duration_hours = round(span / 1h, decimals: 1)
| fieldsAdd logs_per_hour = round(total / (span / 1h), decimals: 0)
| sort total desc

// Content-length statistics, including the 95th percentile
fetch logs, from: now() - 1h
| fieldsAdd content_length = stringLength(content)
| summarize {
avg_length = avg(content_length),
p95_length = percentile(content_length, 95),
min_length = min(content_length),
max_length = max(content_length),
total_logs = count()
}, by: {k8s.namespace.name}
| sort avg_length desc
| limit 15

// Hourly distribution analysis
fetch logs, from: now() - 24h
| fieldsAdd hour_bucket = bin(timestamp, 1h)
| summarize {log_count = count()}, by: {hour_bucket}
| sort hour_bucket asc

// Daily distribution analysis
fetch logs, from: now() - 7d
| fieldsAdd day_bucket = bin(timestamp, 24h)
| summarize {
log_count = count(),
error_count = countIf(status == "ERROR")
}, by: {day_bucket}
| sort day_bucket asc

// Compare current hour to previous hour
fetch logs, from: now() - 2h
| fieldsAdd period = if(timestamp > now() - 1h, "current", else: "previous")
| summarize {count = count()}, by: {period, loglevel}
| sort period asc, count desc

// New error patterns: first seen in the last 30 minutes of a 24-hour window
// (a 1-hour window would call any pattern "new" that simply had not occurred in that hour)
fetch logs, from: now() - 24h
| filter status == "ERROR"
// Collapse UUIDs, then digits: a raw prefix makes every timestamped line unique, and replacing digits alone
// leaves a UUID's hex letters, so every request ID becomes its own "new" pattern
// (validation tenant, 24h of errors: 30,852 digit-only signatures vs 223 with UUIDs collapsed, 10/12/2026)
| fieldsAdd error_sig = substring(replacePattern(replacePattern(content, "[0-9a-fA-F]{8} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{12}", replacement: "<id>"), "[0-9]+", replacement: "#"), from: 0, to: 80)
| summarize {
count = count(),
first_seen = min(timestamp)
}, by: {error_sig, k8s.namespace.name}
| filter first_seen > now() - 30m
| sort first_seen desc
| limit 15

// Top log patterns (by content prefix)
fetch logs, from: now() - 1h
// UUIDs → "<id>", then digits → "#", so timestamps and IDs do not make every line its own pattern
| fieldsAdd pattern = substring(replacePattern(replacePattern(content, "[0-9a-fA-F]{8} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{12}", replacement: "<id>"), "[0-9]+", replacement: "#"), from: 0, to: 60)
| summarize {count = count()}, by: {pattern}
| sort count desc
| limit 25

// Unique log levels and statuses
fetch logs, from: now() - 1h
| summarize {
loglevels = collectDistinct(loglevel),
statuses = collectDistinct(status),
sources = collectDistinct(dt.openpipeline.source)
}

// Log diversity score (unique patterns per namespace)
fetch logs, from: now() - 1h
| fieldsAdd pattern = substring(replacePattern(replacePattern(content, "[0-9a-fA-F]{8} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{4} '-' [0-9a-fA-F]{12}", replacement: "<id>"), "[0-9]+", replacement: "#"), from: 0, to: 50)
| summarize {
total_logs = count(),
unique_patterns = countDistinct(pattern)
}, by: {k8s.namespace.name}
| fieldsAdd diversity_ratio = round((unique_patterns * 100.0) / total_logs, decimals: 2)
| sort diversity_ratio desc
| limit 15
